function addProof(id){if(!proofs[id])return;plot.evidence[id]=true;record('Missing girls investigation · '+proofs[id][0]+': '+proofs[id][1]);savePlot()}
function inspectProof(id,after){const p=proofs[id];modal(p[0],'<div class="paper"><p>'+esc(p[1])+'</p></div>',[['Preserve and record this evidence',()=>{addProof(id);if(after)after();else{close();say('Evidence recorded: '+p[0]+'. Compare it in the missing-girls case file.');}},true],['Leave for now',close]],'THE MISSING GIRLS · PHYSICAL EVIDENCE')}
const oldGain=gain;gain=function(item,kind='study',evidence=false){oldGain(item,kind,evidence);const id={'School note':'roll','Eva Grey photograph':'photo','Portrait showing Eva Grey':'photo','Restored transfer order':'transfer','Mara Ash diary':'diary'}[item];if(id)addProof(id)};
for(const [id,earned]of [['roll',hall.found.includes('School note')],['photo',hall.portrait||study.portrait],['transfer',study.repaired],['diary',study.evidence.includes('Mara Ash diary')]])if(earned&&!plot.evidence[id])addProof(id);
rooms.chapel={title:'The Sealed Chapel',name:'Estate Chapel',chapter:'GROUNDS · CHAPEL',caption:'The warning came from here.',image:'chapel',alt:'Gerouge’s small estate chapel with inscription, service hatch on the right wall and toy bear on the left bench.',message:'The inscription faces the altar. A loosened hatch sits low in the right wall; a toy bear rests on a bench.',back:'approach',hotspots:[['Read the chapel inscription',51,26,'chapelInscription'],['Inspect the service hatch',93,56,'serviceHatch'],['Examine Eva’s toy bear',24,81,'evaBear'],['Follow the garden path to the mansion',9,40,'approach','door']]};
