const oldTravel=travel;travel=function(id){if(id==='chapel'&&!ownsChapelKey()&&!['vault','vestry','stairs','passage'].includes(scene))return notice('The chapel door is locked','Find the chapel key in the entrance-hall console drawer.');if(id==='vault'&&!plot.hatchOpen)return notice('The service hatch is still closed','Document the chapel hatch and open its loosened bolt before entering the vault.');oldTravel(id);if(id==='hall'&&plot.evidence.receipt&&!plot.disturbance){plot.disturbance=true;savePlot();render();tone(132);say('The console drawer has been disturbed. A fresh envelope waits inside. Someone entered the hall while you were below the chapel.')}};
const oldAct=act;act=function(type){const actions={chapelInscription:()=>notice('LET THEM BE NAMED','The inscription repeats the girls’ plea. A personal note may explain why their records were hidden here.'),evaBear:()=>modal('A loose seam in the toy bear','<p>E.G. is stitched into the cloth. A folded note is caught beneath the loose backing seam.</p>',[['Lift the loose seam and unfold the note',()=>inspectProof('eva'),true],['Leave the bear',close]]),serviceHatch:()=>{if(!plot.evidence.hatch)return inspectProof('hatch',()=>modal('The documented service hatch','<p>You have recorded the tool marks. The bolt is already loose; slide it aside without forcing the frame.</p>',[['Slide the bolt and descend',()=>{plot.hatchOpen=true;savePlot();travel('vault')},true],['Stay in the chapel',close]]));modal('The service hatch','<p>Your record of the original position is preserved. The stairs descend into the records vault.</p>',[['Descend to the vault',()=>{plot.hatchOpen=true;savePlot();travel('vault')},true],['Stay',close]])},carbonLedger:()=>inspectProof('carbon'),vaultIndex:()=>inspectProof('roll'),vaultLining:()=>{if(!plot.evidence.receipt)return inspectProof('receipt',()=>notice('A second lining','The access slip is recorded. Lift the lining again to examine the paper underneath.'));inspectProof('audit')},disturbedDrawer:()=>inspectProof('warning')};if(actions[type])return actions[type]();return oldAct(type)};
